import csv

def gerar_relatorio_mensal(dados, caminho):
    with open(caminho, 'w', encoding='utf-8', newline='') as arquivo:
        escritor = csv.writer(arquivo, delimiter=';')
        escritor.writerow(['mes', 'vendas', 'lucro'])
        for registro in dados:
            escritor.writerow([registro['mes'], registro['vendas'], registro['lucro']])
    return list(dados)

